console.log('[md-insert-image] Script loaded'); document.addEventListener('DOMContentLoaded', function () { console.log('[md-insert-image] DOM ready'); let imageModal = null; let imageListContainer = document.getElementById('imageList'); let uploadForm = document.getElementById('uploadImageForm'); let uploadBtn = document.getElementById('uploadImageBtn'); let uploadStatus = document.getElementById('uploadStatus'); let imageUrlInput = document.getElementById('imageUrlInput'); let insertUrlImageBtn = document.getElementById('insertUrlImageBtn'); let selectedTextarea = null; function initModal() { if (!imageModal && document.getElementById('insertImageModal')) { console.log('[md-insert-image] Initializing modal'); imageModal = new bootstrap.Modal(document.getElementById('insertImageModal')); } } function getCurrentCSRFToken() { let metaTag = document.querySelector('meta[name="csrf_token"]'); return metaTag ? metaTag.getAttribute('content') : ''; } document.addEventListener('md-mini:insert-image', function (e) { console.log('[md-insert-image] Insert image event triggered'); initModal(); selectedTextarea = e.detail.textarea; console.log('[md-insert-image] Textarea:', selectedTextarea ? 'found' : 'not found'); if (imageModal) { loadImages(); imageModal.show(); } else { console.error('[md-insert-image] Modal not initialized'); } }); function loadImages() { console.log('[md-insert-image] Loading images'); if (!imageListContainer) { console.error('[md-insert-image] imageListContainer not found'); return } fetch('/api/images', { method: 'GET', headers: { 'Content-Type': 'application/json' } }).then(r => { console.log('[md-insert-image] Response status:', r.status); if (r.status === 401) { console.log('[md-insert-image] Not authenticated'); imageListContainer.innerHTML = '<div class="alert alert-info mb-0">Faça login para usar este recurso</div>'; return [] } return r.json(); }).then(images => { console.log('[md-insert-image] Loaded', images ? images.length : 0, 'images'); if (!images || images.length === 0) { imageListContainer.innerHTML = '<div class="text-center text-body-secondary py-4"><small>Nenhuma imagem disponível. Faça upload de uma nova.</small></div>'; return } let html = ''; images.forEach(img => { html += '<div class="d-flex gap-2 mb-2 p-2" style="border-bottom: 1px solid var(--bs-border-color);">'; html += '<img src="' + escapeHtml(img.thumbnail_url) + '" alt="' + escapeHtml(img.display_name) + '" style="max-width: 60px; max-height: 60px; object-fit: cover; border-radius: 0.25rem; cursor: pointer;" class="select-image-thumb" data-url="' + escapeHtml(img.file_url) + '" data-name="' + escapeHtml(img.display_name) + '">'; html += '<div style="flex: 1; min-width: 0;">'; html += '<div class="small fw-bold text-truncate">' + escapeHtml(img.display_name) + '</div>'; html += '<div class="small text-body-secondary text-truncate">' + escapeHtml(img.description || 'Sem descrição') + '</div>'; html += '<div class="small text-body-secondary">' + escapeHtml(img.created_at || '') + '</div>'; html += '</div>'; html += '<button type="button" class="btn btn-sm btn-outline-primary select-image-btn" data-url="' + escapeHtml(img.file_url) + '" data-name="' + escapeHtml(img.display_name) + '" style="white-space: nowrap;">Inserir</button>'; html += '</div>'; }); imageListContainer.innerHTML = html; document.querySelectorAll('.select-image-btn, .select-image-thumb').forEach(btn => { btn.addEventListener('click', function () { insertImage(this.getAttribute('data-url'), this.getAttribute('data-name')); }); }); }).catch(err => { console.error('[md-insert-image] Error loading images:', err); imageListContainer.innerHTML = '<div class="alert alert-danger mb-0">Erro ao carregar imagens: ' + err + '</div>'; }); } if (uploadForm) { uploadForm.addEventListener('submit', function (e) { e.preventDefault(); let file = document.getElementById('imageFileInput').files[0]; if (!file) { uploadStatus.innerHTML = '<div class="alert alert-warning mb-0">Selecione uma imagem</div>'; return } console.log('[md-insert-image] Uploading image:', file.name); uploadStatus.innerHTML = '<div class="alert alert-info mb-0">Enviando...</div>'; uploadBtn.disabled = true; let formData = new FormData(); formData.append('file', file); formData.append('original_filename', file.name); formData.append('description', document.getElementById('imageDescription').value || file.name); formData.append('filetag', 'forum'); formData.append('csrf_token', getCurrentCSRFToken()); fetch('/files/upload', { method: 'POST', body: formData }).then(r => r.text()).then(html => { console.log('[md-insert-image] Upload response received, length:', html.length); if (html.indexOf('alert-danger') !== -1 || html.indexOf('error') !== -1 || html.indexOf('Error') !== -1) { console.error('[md-insert-image] Upload error in response'); uploadStatus.innerHTML = '<div class="alert alert-danger mb-0">Erro ao fazer upload. Verifique o tamanho do arquivo (máx. 500 MB).</div>'; } else { console.log('[md-insert-image] Upload successful'); uploadStatus.innerHTML = '<div class="alert alert-success mb-0">Upload concluído. Recarregando lista...</div>'; document.getElementById('imageFileInput').value = ''; document.getElementById('imageDescription').value = ''; setTimeout(function () { loadImages(); uploadStatus.innerHTML = ''; }, 1500); } }).catch(err => { console.error('[md-insert-image] Upload error:', err); uploadStatus.innerHTML = '<div class="alert alert-danger mb-0">Erro ao fazer upload: ' + err + '</div>'; }).finally(() => { uploadBtn.disabled = false; }); }); } if (insertUrlImageBtn) { insertUrlImageBtn.addEventListener('click', function () { let url = imageUrlInput.value.trim(); if (!url) { console.warn('[md-insert-image] Empty URL'); return } insertImage(url, 'Imagem'); }); } function insertImage(url, name) { console.log('[md-insert-image] Inserting image:', url); if (!selectedTextarea) { console.error('[md-insert-image] No textarea selected'); return } let markdown = '![' + name + '](' + url + ')'; selectedTextarea.value += '\n' + markdown; selectedTextarea.dispatchEvent(new Event('change', { bubbles: true })); console.log('[md-insert-image] Image markdown inserted'); if (imageModal) imageModal.hide(); } function escapeHtml(text) { if (!text) return ''; let map = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }; return text.replace(/[&<>"']/g, m => map[m]); } });


